import Foundation

extension CommunityGuides {
    static let volunteeringGuide = DirectoryGuide(
        cardSummary: .init(ukrainian: "Пошук місця, умови, страхування та підтвердження досвіду", german: "Einsatzsuche, Bedingungen, Versicherung und Nachweis"),
        introduction: .init(ukrainian: "Оберіть добровільну справу за часом і навичками, а перед початком з’ясуйте відповідальність організації. Волонтерство й оплачувана робота мають різні правила.", german: "Ehrenamt nach Zeit und Fähigkeiten wählen und vor Beginn die Verantwortung der Organisation klären. Freiwilligentätigkeit und bezahlte Arbeit haben unterschiedliche Regeln."),
        sections: [
            .init("advice", "person.2", "Отримайте допомогу з вибором", "Bei der Auswahl beraten lassen", "На сторінці Freiwilligenzentren оберіть свою землю й зв’яжіться з центром. Консультант допоможе підібрати організацію за вашою мовою, часом, навичками та мобільністю. Скажіть, які завдання вам не підходять, і попросіть контакт координатора та умови пробного візиту.", "Auf der Freiwilligenzentren-Seite das Bundesland wählen und das Zentrum kontaktieren. Beratung hilft, eine Organisation nach Sprache, Zeit, Fähigkeiten und Mobilität zu finden. Unpassende Aufgaben nennen und Kontakt der Koordination sowie Bedingungen für einen Schnuppertermin erfragen.", source: volunteerCenters),
            .init("find", "magnifyingglass", "Знайдіть проєкт самостійно", "Projekt selbst suchen", "На порталі «freiwillig engagiert» шукайте можливості за місцем і темою: освіта, сусідська допомога, природа чи культура. Перевірте дату оголошення, адресу, тривалість і вимоги до мови або підготовки. Напишіть організатору, скільки часу реально можете приділяти, і попросіть опис конкретних завдань до початку.", "Auf „freiwillig engagiert“ Einsätze nach Ort und Thema suchen: Bildung, Nachbarschaftshilfe, Natur oder Kultur. Veröffentlichungsdatum, Ort, Dauer und Anforderungen an Sprache oder Ausbildung prüfen. Dem Träger die tatsächlich verfügbare Zeit nennen und vor Beginn konkrete Aufgabenbeschreibung verlangen.", source: volunteerProjects),
            .init("verify", "checkmark.shield", "Перевірте організацію", "Organisation prüfen", "Попросіть юридичну назву, адресу й людину, що координує волонтерів. Якщо це зареєстрована волонтерська організація, перевірте її у FWO-Register за назвою або FWO-номером; перелік може бути неповним, тому відсутність запису сама по собі не доводить шахрайство. Не надсилайте паспорт у приватний чат і не сплачуйте «внесок за допуск» без письмового пояснення.", "Rechtlichen Namen, Anschrift und Freiwilligenkoordination erfragen. Eine registrierte Freiwilligenorganisation im FWO-Register nach Name oder FWO-Nummer prüfen; die Liste kann unvollständig sein, ein fehlender Eintrag beweist allein keinen Betrug. Pass nicht in privaten Chats versenden und keine „Aufnahmegebühr“ ohne schriftliche Erklärung zahlen.", source: volunteerRegister),
            .init("agreement", "doc.text", "Домовтеся про межі й витрати", "Aufgaben und Kosten vereinbaren", "До першої зміни уточніть час, місце, навчання, супровід, можливість припинити участь та кому повідомляти про проблему. Письмово запитайте, чи відшкодовують квитки або інші витрати й чи виплачують компенсацію. Якщо від вас очікують регулярної продуктивної роботи замість штатного працівника, попросіть пояснити правову форму та зверніться по трудову консультацію.", "Vor dem ersten Einsatz Zeit, Ort, Einschulung, Begleitung, Ausstieg und Ansprechperson bei Problemen klären. Schriftlich nach Fahrtkosten, anderen Auslagen und Aufwandsentschädigung fragen. Wird regelmäßige produktive Arbeit statt einer bezahlten Stelle erwartet, Rechtsform erklären lassen und arbeitsrechtliche Beratung einholen.", source: volunteerRights),
            .init("insurance", "cross.case", "Уточніть страхування до початку", "Versicherung vor Beginn klären", "Запитайте організацію, хто покриває нещасний випадок і відповідальність перед іншими саме для вашого завдання та дороги до нього. Захист залежить від організації, землі й виду участі; загального правила «кожен волонтер автоматично застрахований» немає. Для роботи з дітьми чи в кризовій службі уточніть навчання, перевірки й правила безпеки до допуску.", "Organisation vorab fragen, wer Unfall- und Haftpflichtschutz für konkrete Aufgabe und Weg trägt. Der Schutz hängt von Träger, Bundesland und Art des Einsatzes ab; „jede freiwillige Tätigkeit ist automatisch versichert“ gilt nicht allgemein. Bei Kindern oder Krisendiensten Einschulung, Nachweise und Sicherheitsregeln vor dem Einsatz klären.", source: volunteerRights),
            .init("benefits", "person.crop.rectangle", "Якщо отримуєте виплати або шукаєте роботу", "Bei Leistungsbezug oder Arbeitssuche", "Волонтерство не повинно заважати обов’язковим зустрічам і доступності для AMS. Якщо отримуєте Arbeitslosengeld/Notstandshilfe, до початку уточніть у своєму AMS вплив годин і можливої компенсації; зміни, які можуть вплинути на виплату, повідомляйте вчасно. Для Grundversorgung запитайте її відповідальну службу про правила вашої землі. Не називайте оплачувану зміну «волонтерством», щоб обійти правила.", "Ehrenamt darf verbindliche Termine und Verfügbarkeit für das AMS nicht beeinträchtigen. Bei Arbeitslosengeld/Notstandshilfe vor Beginn Einsatzstunden und mögliche Entschädigung mit dem eigenen AMS klären; anspruchsrelevante Änderungen rechtzeitig melden. Bei Grundversorgung die zuständige Stelle nach Landesregeln fragen. Bezahlte Schichten nicht als „Ehrenamt“ bezeichnen, um Regeln zu umgehen.", source: amsChanges),
            .init("record", "checkmark.seal", "Отримайте підтвердження досвіду", "Erfahrung nachweisen", "Ведіть записи про дати, завдання й навички. Наприкінці попросіть організацію оформити Freiwilligenpass або Nachweis über freiwillige Tätigkeiten разом з вами; існує паперовий і цифровий варіант. Уточніть, хто в організації має право підписати підтвердження. Це корисне доповнення до заявки на роботу, але не замінює диплома чи професійного дозволу.", "Daten, Aufgaben und erworbene Fähigkeiten festhalten. Am Ende mit der Organisation Freiwilligenpass oder Nachweis über freiwillige Tätigkeiten erstellen; Papier- und Digitalform sind verfügbar. Klären, wer den Nachweis in der Organisation bestätigen darf. Er ergänzt Bewerbungen, ersetzt aber weder Abschluss noch Berufszulassung.", source: volunteerRecord)
        ], sources: [volunteerCenters, volunteerProjects, volunteerRegister, volunteerRights, amsChanges, volunteerRecord]
    )
}
